rules.pseudocode:
rsiVal = WFSafe_RSI(close, rsiLength);   // series variable; history read as rsiVal[j]
lo = 50 - bandHalfWidth; hi = 50 + bandHalfWidth;
for (b = 1; b <= maxWaitBars; ++b) {
  if (!(rsiVal[b] < lo)) continue;
  if (any j in b+1..b+bandBars with rsiVal[j] < lo || rsiVal[j] > hi) continue;   // band held before the break
  if (any j in 1..b-1 with rsiVal[j] >= lo) continue;                            // back in the band: invalidated
  if (any j in 1..b-1 with close[j] > open[j]) continue;                         // not the first green bar
  return close[0] > open[0];
}
return false;

rsiVal = WFSafe_RSI(close, rsiLength);
lo = 50 - bandHalfWidth; hi = 50 + bandHalfWidth;
for (j = 1; j <= bandBars; ++j) if (rsiVal[j] < lo || rsiVal[j] > hi) return false;
return (rsiVal[0] < lo || rsiVal[0] > hi) && close[0] > open[0];

touch[i] = el_ge(high[i], bbUpper[i]);   // bbUpper = Average(close, N) + k * StdDev(close, N), population
// current episode: consecutive touch bars 0..e-1; previous episode: the next run of touch bars before a gap
prevHi = max high of the previous episode (within lookback);
curHiBefore = max high of bars 1..e-1 of the current episode;
long = touch[0] && havePrev && el_gt(high[0], prevHi) && !(e > 1 && el_gt(curHiBefore, prevHi));

T = most recent i in 1..L with el_ge(high[i], bbUpper[i]);
ok = haveT;
for (i = 1; i < T; ++i) if (el_le(low[i], bbLower[i]) || el_gt(close[i], high[T])) ok = false;
long = ok && !el_le(low[0], bbLower[0]) && el_gt(close[0], high[T]);

T = most recent i in 1..L with el_ge(high[i], highest(high, X)[i]) && el_ge(high[i], bbUpper[i]);
levelAt(i) = average(close, length)[i] - retraceDevs * stddev(close, length)[i];   // retraceDevs 0 = middle band, numDevs = lower band
level = levelAt(0);
first = true; for (i = 1; i < T; ++i) if (el_le(low[i], levelAt(i))) first = false;
long = haveT && first && el_le(low[0], level);
